CODE_PATTERN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{1,39}$")


def backfill_owner_source_codes(apps, schema_editor):
    """Create explicit, unverified records for exact code lines in owner sources.

    Free-text lines such as "MALLARD10 - 10% off" stay source text. YouTube API
    descriptions are excluded because that text expires with its saved source.
    """
    Source = apps.get_model("audit", "Source")
    DiscountCode = apps.get_model("audit", "DiscountCode")
    for source in Source.objects.exclude(codes="").filter(youtube_video_id="").iterator():
        seen = set()
        for line in source.codes.splitlines():
            value = line.strip()
            if not CODE_PATTERN.fullmatch(value) or value.casefold() in seen:
                continue
            seen.add(value.casefold())
            record, _ = DiscountCode.objects.get_or_create(
                project_id=source.project_id,
                code__iexact=value,
                defaults={"code": value},
            )
            record.sources.add(source)


